import {readApiBase,apiEndpoint} from './api-client.mjs';
import {classifyInterviewRequest,conversationControl,buildAnswerDraft} from './interview-assist.mjs';
import {suggestNextStep,inferDocumentType} from './journey.mjs';
import {knowledge,analyze,makePlan,questions,interviewFeedback,retrieve,sampleResume,sampleJob,statusLabels,reviewResume,routeIntent} from './engine.mjs';
import {readResume} from './uploads.mjs';
const $=s=>document.querySelector(s);
let apiConfig={configured:false};let apiBase='';
try{apiBase=await readApiBase();if(['127.0.0.1','localhost'].includes(location.hostname))apiBase='';const response=await fetch(apiEndpoint(apiBase,'/api/status'),{signal:AbortSignal.timeout(3000)});if(response.ok)apiConfig=await response.json()}catch{}
const liveEnabled=apiConfig.configured===true;
let liveHistory=[],liveBusy=false,liveController=null,liveVersion=0;
let resume='',job='',role='',result=null,waiting='idle',questionIndex=0,docs=[...knowledge],uploadVersion=0,transcript=[],completed=new Set();
let requestedTask=null,journeyStage=0,lastTaskMessage='',draftTopic='introduction',draftQuestion='',practiceTopic=null,draftActive=false;
let profile={hoursPerWeek:3,degree:'',experience:'',goal:''};
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').hidden=true,5000)}
function scroll(){requestAnimationFrame(()=>$('#chat-scroll').scrollTo({top:$('#chat-scroll').scrollHeight,behavior:'smooth'}))}
function say(text,speaker='coach'){ $('#welcome').hidden=true;const message=node('article',undefined,'message '+speaker),avatar=node('div',speaker==='coach'?'✳':'Y','message-avatar'),body=node('div',undefined,'message-body'),content=node('div',undefined,'message-content');body.append(node('div',speaker==='coach'?'Career Compass':'You','message-label'));content.append(node('p',text));body.append(content);message.append(avatar,body);$('#messages').append(message);transcript.push({speaker,text});scroll();return content}
function paragraph(target,text,cls){target.append(node('p',text,cls))}
function actions(target,list){const tools=node('div',undefined,'message-tools');for(const [label,action] of list){const b=node('button',label,'chip');b.type='button';b.dataset.action=action;tools.append(b)}target.append(tools);scroll()}
function status(){const bits=[];if(resume)bits.push('Resume added');if(job)bits.push('Target job added');$('#context-status').textContent=bits.length?'✓ '+bits.join(' · '):(liveEnabled?'AI processing enabled · Use redacted data':'◇ Your conversation stays in this tab');$('#change-context').hidden=!bits.length;$('#input-hint').textContent=waiting==='resume'?'Share your experience or attach your resume':waiting==='job'?'Share the opportunity you want to prepare for':waiting==='answer'?'Tell your story · Enter to send, Shift + Enter for a new line':waiting==='draft-context'?'Share only the facts you want in your draft':'Tell me what you want to work on next';$('#message').placeholder=waiting==='resume'?'Paste your resume, projects, and experience here…':waiting==='job'?'Paste the target job description here…':waiting==='answer'?'Share your answer in your own words…':waiting==='draft-context'?'Your degree or current role, a real example, and the opportunity…':'What would you like to work toward?';const stage=(waiting==='answer'||draftActive)?3:!resume?0:!job?1:Math.max(2,journeyStage);['stage-context','stage-opportunity','stage-evidence','stage-action'].forEach((id,i)=>{const item=$('#'+id);item.classList.toggle('current',i===stage);item.classList.toggle('done',draftActive?Boolean((i===0&&(resume||profile.degree||profile.experience))||(i===1&&job)||(i===2&&result)):i<stage);if(i===stage)item.setAttribute('aria-current','step');else item.removeAttribute('aria-current')});$('#coach-next-step').textContent=draftActive?'We’re shaping your interview answer. Use the starting draft, add your own facts, or choose to practice it.':waiting==='answer'?'We’re practicing one answer at a time. You can pause or change direction whenever you need.':!resume?'Tell me what you’re working toward, then share the experience you want to build on.':!job?'Next, share a job description so I can keep the guidance specific.':journeyStage===3?'You have a next step to work on. Ask a follow-up or tell me what you’d like to change.':suggestNextStep(result).message;}
function askResume(){draftActive=false;waiting='resume';say('Let’s start with your experience. Paste your resume below or attach a PDF, DOCX, TXT, or MD file using the ＋ button. Coursework, volunteering, and campus projects count too.\n\nI’ll then ask for a job description so we can compare them.');status();$('#message').focus()}
function askJob(){draftActive=false;waiting='job';say('Thanks, I have your resume. What opportunity would you like to compare it with?\n\nPaste the job description below. Include the job title on the first line if you have it.');status();$('#message').focus()}
function ensureComparison(){if(!resume){askResume();return false}if(!job){askJob();return false}return true}
function source(target,d){const card=node('div',undefined,'source');if(d.url){const a=node('a',d.title+' ↗');a.href=d.url;a.target='_blank';a.rel='noopener noreferrer';card.append(a)}else card.append(node('b',d.title));card.append(node('small',d.publisher+' · Source ID: '+d.id+' · Reviewed '+(d.reviewed||'not recorded')),node('p',d.text));target.append(card)}
function showSources(){const box=say('Here’s the guidance retrieved for your comparison. These are locally stored summaries with links to their original sources; they are not live web-search results.');for(const d of result?.sources||retrieve('resume interview experience',docs))source(box,d);scroll()}
function evidence(target,rows){for(const r of rows){const detail=node('details',undefined,'evidence');detail.append(node('summary',r.skill+' · '+statusLabels[r.status]+' · '+r.priority));detail.append(node('p','Job description'),node('blockquote',r.jobEvidence));detail.append(node('p','Your resume'),node('blockquote',r.resumeEvidence||'No recognized phrase found.'));detail.append(node('p',r.explanation,'small-note'));target.append(detail)}}
function compare(){try{result=analyze(resume,job,role,docs);completed.clear();journeyStage=2;$('#session-title').textContent=role||'Your next chapter';waiting='idle';const next=suggestNextStep(result);const box=say('I’ve reviewed the experience you shared against '+result.role+'. Here’s where I would focus next.');box.append(node('h3','What you can build on'));paragraph(box,result.found.length?result.found.slice(0,5).map(r=>r.skill+' ('+statusLabels[r.status].toLowerCase()+')').join(', ')+'.':'I couldn’t recognize positive evidence for the skills in this posting. Let’s check the source text before drawing conclusions.');if(result.gaps.length){box.append(node('h3','What needs a closer look'));paragraph(box,result.gaps.slice(0,3).map(r=>r.skill+' — '+statusLabels[r.status].toLowerCase()+'; '+r.priority+' in the posting').join('\n'))}box.append(node('h3','My suggested next step'));paragraph(box,next.message);actions(box,[[next.label,next.action],next.action==='interview'?['Make a short plan','plan']:['Practice an interview','interview']]);const supporting=node('details',undefined,'supporting-details');supporting.append(node('summary','Evidence, sources and how this worked'));paragraph(supporting,'These are rule-based observations. The excerpts let you check both the recommendation and the limitations. A missing mention does not prove you lack a skill.','small-note');if(result.manualReview.length){supporting.append(node('h3','Qualifications to review manually'));for(const line of result.manualReview)paragraph(supporting,line)}actions(supporting,[['Inspect skill evidence','gaps'],['Read retrieved guidance','sources'],['See the workflow','trace']]);box.append(supporting);status();const requested=requestedTask;requestedTask=null;if(requested==='plan')showPlan();else if(requested==='gaps')showGaps();}catch(error){say(error.message);status()}}
function showGaps(){if(!ensureComparison())return;if(!result){compare();return}const box=say('Let’s look at the evidence. Open any skill below to see the exact phrases from your documents. An absent phrase may simply mean your resume needs a clearer example.');evidence(box,[...result.gaps,...result.found]);if(!result.rows.length)paragraph(box,'No dictionary skills were detected for this role. This prototype’s dictionary is limited.');actions(box,[['Create an action plan','plan'],['See guidance sources','sources']])}
function showPlan(){if(!ensureComparison())return;journeyStage=3;if(!result)result=analyze(resume,job,role,docs);waiting='idle';const box=say('Here’s a four-week starting template based on your comparison. Adapt the scope and timing to your schedule. You can check off milestones as you go.');for(const [i,p]of makePlan(result,profile).entries()){const label=node('label',undefined,'plan-step'),check=node('input');check.type='checkbox';check.checked=completed.has(i);check.setAttribute('aria-label','Complete '+p.title);check.addEventListener('change',()=>{check.checked?completed.add(i):completed.delete(i);for(const other of document.querySelectorAll(`input[data-week="${i}"]`))other.checked=check.checked});check.dataset.week=i;const copy=node('div');copy.append(node('small',p.week),node('b',p.title),node('p',p.text),node('p','Deliverable: '+p.deliverable),node('p','Self-check: '+p.check));label.append(check,copy);box.append(label);transcript.push({speaker:'plan',text:p.week+': '+p.title+'\n'+p.text})}actions(box,[['Practice an interview','interview'],['Review skill evidence','gaps']]);status()}
function askQuestion(){journeyStage=3;waiting='answer';const box=say('Question '+(questionIndex+1)+' of 5\n\n'+(questionIndex===0&&practiceTopic==='introduction'?'Tell me about yourself and how your background connects to the opportunity.':questions(result)[questionIndex]));paragraph(box,'Use a real example: set the situation, explain your task and actions, then describe the result. This practice uses template questions and a keyword-based self-review.','small-note');actions(box,[['Skip this question','next-question'],['Leave interview practice','finish-interview']]);status();$('#message').focus()}
function handleAction(action,echo=true){
 if(liveBusy)return;
 if(liveEnabled){
  const prompts={resume:'Please review my resume and help me prepare for my target opportunity.',plan:'Create a practical four-week action plan using my available weekly hours.',gaps:'Compare my resume with my target job. Explain supported skills, missing mentions and uncertainties.',interview:'Start a mock interview. Ask one question at a time.', 'interview-draft':lastTaskMessage||'Help me draft an interview answer.', 'draft-introduction':'Help me draft an answer to tell me about yourself.', 'draft-details':'Help me tailor the previous answer using my supplied details. Ask for only what is still missing.', 'practice-draft':'Help me practice the answer we just drafted. Ask one question at a time.', 'next-question':'Ask the next mock interview question.', 'finish-interview':'Stop the mock interview.', 'resume-tips':'Improve my resume bullets without inventing facts or outcomes.'};
  if(prompts[action]){if(action==='resume'&&!resume){askResume();return}receive(prompts[action]);return}
 }
if(['resume','plan','gaps','interview','finish-interview','next-question','practice-draft'].includes(action))draftActive=false;if(action==='interview-draft'){showAnswerDraft(lastTaskMessage);return}if(action==='draft-introduction'){showAnswerDraft('Help me answer tell me about yourself.');return}if(action==='draft-details'){waiting='draft-context';say('You already have a starting template. To tailor it, send one message with Degree/current role, Project or responsibility, and Target role. You can use labels such as “Target role: Business Analyst Intern”. Share only facts you want included.');status();return}if(action==='interview-help'){waiting='idle';const box=say('I can help in two ways: draft an answer to a question, or run a mock interview. Which would be useful?');actions(box,[['Help draft my introduction','draft-introduction'],['Start a mock interview','interview']]);status();return}if(['plan','gaps'].includes(action)&&(!resume||!job))requestedTask=action;if(extraAction(action))return;if(action==='sources'){showSources();return}if(action==='next-question'){questionIndex=(questionIndex+1)%5;askQuestion();return}if(action==='finish-interview'){waiting='idle';const box=say('Practice paused. What would you like to work on next?');actions(box,[['Review my resume','resume'],['Make an action plan','plan']]);status();return}const prompts={resume:'Help me review my resume.',gaps:'Show me my skill insights.',interview:'Help me practice for an interview.',plan:'Help me plan my next steps.'};if(echo&&prompts[action])say(prompts[action],'user');if(action==='resume'){if(resume&&job){compare()}else if(resume)askJob();else askResume()}else if(action==='gaps'){showGaps()}else if(action==='plan'){showPlan()}else if(action==='interview'){questionIndex=0;askQuestion()}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)handleAction(b.dataset.action)});
function receive(text){if(liveBusy)return;say(text,'user');if(liveEnabled){sendLive(text);return}const control=conversationControl(text);if(control){waiting='idle';requestedTask=null;if(control==='stop'){draftActive=false;say('Practice paused. Tell me what you would like help with next.');status();return}if(classifyInterviewRequest(lastTaskMessage)?.intent==='interview-draft'){const box=say('Let’s change the approach rather than repeat the same draft. I can tailor it to your actual experience, or help with a different interview question.');actions(box,[['Use my details to tailor it','draft-details'],['Draft a different answer','draft-other']]);status();return}const box=say('I misunderstood what you wanted. Let’s change direction. I can help you draft an interview answer instead of asking practice questions.');actions(box,[['Help draft my introduction','draft-introduction'],['Ask me a mock question','interview']]);status();return}const interviewRequest=classifyInterviewRequest(text);if(interviewRequest){lastTaskMessage=text;practiceTopic=interviewRequest.topic;if(interviewRequest.intent==='interview-draft'||interviewRequest.intent==='interview-help'||interviewRequest.intent==='interview'){requestedTask=null;handleAction(interviewRequest.intent,false);return}}if(waiting==='draft-context'){showAnswerDraft(draftQuestion,text);return}if(waiting==='draft-question'){showAnswerDraft(text);return}const inferred=waiting==='idle'?inferDocumentType(text):null;if(inferred==='resume'){resume=text;result=null;completed.clear();if(job)compare();else askJob();return}if(inferred==='job'){job=text;const first=text.split('\n')[0].trim();role=first.length<=120?first:'Your target role';if(resume)compare();else askResume();return}const intent=routeIntent(text);if(intent)lastTaskMessage=text;if(intent&&(waiting==='idle'||/^(help|please|can you|show|start|practice|review|create|build|make)\b/i.test(text))){handleAction(intent,false);return}
 if(waiting==='resume'){if(text.length<40){say('Please share a little more detail—at least 40 characters of education, skills, projects, or experience.');return}resume=text;result=null;completed.clear();if(job)compare();else askJob();return}
 if(waiting==='job'){if(text.length<40){say('Please paste a longer job description with responsibilities and qualifications—at least 40 characters.');return}job=text;const first=text.split('\n')[0].trim();role=first.length<=120?first:'Your target role';compare();return}
 if(waiting==='answer'){if(text.trim().length<30){say('Try a few sentences so you can review the structure. What happened, what did you do, and what was the outcome?');return}const f=interviewFeedback(text),box=say('Let’s review the structure of your answer ('+f.words+' words).');for(const item of f.items)paragraph(box,(item.signal?'✓ Possible signal':'○ Check this')+': '+item.label+' — '+item.tip);paragraph(box,f.note,'small-note');box.append(node('h3','A follow-up to strengthen your story'));paragraph(box,f.followUp);actions(box,[['Try another question','next-question'],['Finish practice','finish-interview']]);return}
 const found=retrieve(text,docs,3);const box=say(found.length?'I found these passages in the career resource library. This prototype can retrieve guidance and run the workflows below; it cannot yet generate open-ended AI advice.':'I can help compare a resume with a job, create a starting plan, or guide interview practice. I didn’t find a relevant passage for that question in the current library.');for(const d of found)source(box,d);actions(box,[['Review my resume','resume'],['Practice an interview','interview'],['Create a plan','plan']])}
$('#chat-form').addEventListener('submit',e=>{e.preventDefault();const text=$('#message').value.trim();if(!text||liveBusy)return;$('#message').value='';$('#message').style.height='';receive(text)});$('#message').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#chat-form').requestSubmit()}});$('#message').addEventListener('input',e=>{e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,175)+'px'});
$('#sample').addEventListener('click',()=>{say('Show me a sample resume conversation.','user');resume=sampleResume;job=sampleJob;role='Business Analyst Intern';const box=say('Let’s use Jordan Lee, a fictional MIS student exploring a Business Analyst internship. The sample resume mentions SQL, Excel, Tableau, Python, and academic projects.');const details=node('details',undefined,'evidence');details.append(node('summary','View the fictional resume and target job'),node('p',sampleResume),node('p',sampleJob));box.append(details);if(liveEnabled)receive('Review this fictional resume against the Business Analyst Intern job, and recommend one useful next step.');else compare()});
function panel(title){$('#panel-title').textContent=title;$('#panel-content').replaceChildren();if(!$('#panel').open)$('#panel').showModal();return $('#panel-content')}
$('#close-panel').addEventListener('click',()=>$('#panel').close());
$('#change-context').addEventListener('click',()=>{const box=panel('Update your comparison');paragraph(box,'The next message you send will replace the selected input and invalidate the previous comparison.');for(const [label,next]of[['Replace my resume','resume'],['Replace the job description','job']]){const button=node('button',label,'chip');button.addEventListener('click',()=>{$('#panel').close();waiting=next;say(next==='resume'?'Paste or attach your updated resume. I’ll keep your target job and rebuild the comparison.':'Paste the new job description. I’ll keep your resume and rebuild the comparison.');status();$('#message').focus()});box.append(button)}});
function openLibrary(){const box=panel('Resource library');paragraph(box,'Search locally stored source summaries using BM25 keyword ranking. Your added guidance stays in this tab.');const label=node('label','Search guidance'),input=node('input');input.placeholder='e.g. resume evidence or interview';input.id='source-search';label.htmlFor=input.id;const results=node('div');const render=()=>{results.replaceChildren();const list=input.value.trim()?retrieve(input.value,docs,docs.length):docs;for(const d of list)source(results,d);if(!list.length)paragraph(results,'No matching passages. Try a different phrase.')};input.addEventListener('input',render);box.append(label,input,results);render();const details=node('details');details.append(node('summary','Add guidance to this tab'));const titleLabel=node('label','Source title'),title=node('input'),textLabel=node('label','Guidance text'),text=node('textarea');title.id='source-title';text.id='source-text';titleLabel.htmlFor=title.id;textLabel.htmlFor=text.id;title.maxLength=160;text.maxLength=12000;const add=node('button','Add to library','chip');add.addEventListener('click',()=>{if(title.value.trim().length<3||text.value.trim().length<40){notify('Add a title and at least 40 characters of guidance.');return}if(docs.length>=27){notify('This session’s library is full. Start a new conversation to reset.');return}docs.push({id:'custom-'+crypto.randomUUID(),title:title.value.trim(),text:text.value.trim(),publisher:'Added by you · not independently verified',url:null});title.value='';text.value='';input.value='';render();notify('Added to this tab’s library. Future retrieval will include it.')});details.append(titleLabel,title,textLabel,text,add);box.append(details)}
$('#about').addEventListener('click',()=>{const box=panel('About Career Compass');if(liveEnabled){paragraph(box,'One AI career coach uses server-side OpenAI requests and bounded local tools. Generated advice can be incorrect. Verify personal claims and supporting sources.');paragraph(box,'When you send a message, recent chat, your supplied resume/job text, optional goals and retrieved passages are sent through the local server to OpenAI. Requests set store:false; this does not promise zero provider retention. The app does not save conversations on its server. Downloaded sessions and exports may contain personal information.');paragraph(box,'Retrieved passages are stored summaries and authored frameworks, not live web search. Known source IDs are checked, but citation support and correctness still require review.');return}paragraph(box,'Career Compass is a student career prototype with a chatbot interface. Replies are templates and local retrieval results. No language model is connected.');for(const [title,text]of[['AI-assisted coding · built','Codex assisted with the interface, document extraction, comparison logic, retrieval and tests.'],['RAG · retrieval built','BM25 retrieves guidance passages with source metadata. Model-generated advice grounded in those passages remains pending.'],['AI agent · pending','The current workflows use fixed rules. A model-driven agent that selects tools and reasons over their outputs has not been connected.'],['Privacy','Resume text, job descriptions, answers, added sources and progress stay in this tab’s memory. A new conversation or reload clears them. Downloaded chat exports stay on your device. External fonts and source links use the network.'],['Limits','Phrase matches can miss synonyms or negation. Limited rules distinguish evidence status and required/preferred wording. They do not assess proficiency, hiring odds or eligibility; degree and experience statements need manual review. PDF/DOCX extraction may omit or reorder text.']]){box.append(node('h3',title));paragraph(box,text)}});
$('#attach').addEventListener('click',()=>$('#resume-file').click());$('#resume-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;const version=++uploadVersion;$('#send').disabled=true;$('#attach').disabled=true;$('#input-hint').textContent='Reading your resume locally…';try{const text=await readResume(file);if(version!==uploadVersion)return;resume=text;result=null;completed.clear();say('Attached resume: '+file.name,'user');const box=say('I extracted the resume text locally. Please review it for missing or reordered content before using the comparison.');const detail=node('details',undefined,'evidence');detail.append(node('summary','Review extracted text'),node('p',text));box.append(detail);if(job){waiting='idle';actions(box,[['Edit extracted text','edit-resume'],['Compare with my target job','resume']]);status()}else {actions(box,[['Edit extracted text','edit-resume']]);askJob()}}catch(error){if(version===uploadVersion){say(error.message);notify(error.message)}}finally{if(version===uploadVersion){$('#send').disabled=false;$('#attach').disabled=false;$('#resume-file').value='';status()}}});
$('#download').addEventListener('click',()=>{if(!transcript.length){notify('Start a conversation first, then export it.');return}const sections=['# Career Compass conversation',liveEnabled?'AI mode: generated advice with retrieved guidance; verify factual claims.':'Practice mode: templates and local retrieval. No live AI connected.','',...[...document.querySelectorAll('.message')].map(m=>'## '+(m.classList.contains('user')?'You':'Career Compass')+'\n'+m.querySelector('.message-content').textContent),'','This export may contain personal resume information.'];const url=URL.createObjectURL(new Blob([sections.join('\n\n')],{type:'text/markdown'})),a=node('a');a.href=url;a.download='career-compass-chat.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
function reset(){liveVersion++;liveController?.abort();liveController=null;liveHistory=[];setLiveBusy(false);uploadVersion++;resume='';job='';role='';result=null;waiting='idle';questionIndex=0;docs=[...knowledge];transcript=[];completed.clear();profile={hoursPerWeek:3,degree:'',experience:'',goal:''};requestedTask=null;journeyStage=0;lastTaskMessage='';draftTopic='introduction';draftQuestion='';practiceTopic=null;draftActive=false;$('#messages').replaceChildren();$('#welcome').hidden=false;$('#message').value='';$('#message').style.height='';$('#resume-file').value='';$('#send').disabled=false;$('#attach').disabled=false;$('#session-title').textContent='Your next chapter';if($('#panel').open)$('#panel').close();status();$('#chat-scroll').scrollTop=0;$('#message').focus()}
$('#new-chat').addEventListener('click',reset);$('.brand').addEventListener('click',e=>{e.preventDefault();reset()});status();

$('#mobile-tools').addEventListener('click',()=>{const box=panel('Conversation options');paragraph(box,'Manage this conversation. The coach will guide the career work in chat.');const fresh=node('button','New conversation','chip');fresh.addEventListener('click',reset);box.append(fresh);for(const [label,action]of [['Update my goals and time budget','profile'],['Save session file','save-session'],['Open session file','open-session'],['Assignment evidence','project']]){const button=node('button',label,'chip');button.addEventListener('click',()=>{$('#panel').close();handleAction(action)});box.append(button)}const resources=node('button','Guidance sources','chip');resources.addEventListener('click',openLibrary);box.append(resources)});

function extraAction(action){if(action==='draft-other'){waiting='draft-question';say('Which interview question would you like an answer for? Paste the question, and I’ll give you a starting draft rather than start a mock interview.');status();return true}if(action==='practice-draft'){practiceTopic=draftTopic==='introduction'?'introduction':null;questionIndex=0;askQuestion();return true}
 if(action==='resume-tips'){if(!resume){askResume();return true}const review=reviewResume(resume),box=say('Let’s make your resume more specific without inventing achievements. These are rule-based checks and light edits; bracketed prompts need your own verified facts.');for(const check of review.checks)paragraph(box,(check.present?'✓ Detected':'○ Review')+': '+check.label);for(const b of review.bullets){const d=node('details',undefined,'evidence');d.append(node('summary','Review a resume bullet'),node('p','Original: '+b.original),node('p','Light edit: '+b.draft),node('p','Structure to complete: '+b.template));for(const q of b.questions)d.append(node('p',q));box.append(d)}if(!review.bullets.length)paragraph(box,'Add a specific project, volunteer activity or work task to get bullet-level feedback.');paragraph(box,review.note,'small-note');actions(box,[['Update my resume','edit-resume'],['See guidance sources','sources']]);return true}
 if(action==='edit-resume'){waiting='resume';$('#message').value=resume;$('#message').focus();say('Edit the extracted or pasted resume in the message box, then send it. The next message replaces your resume and rebuilds the comparison when a job is available.');status();return true}
 if(action==='trace'){if(!result){say('Run a comparison first to inspect the workflow.');return true}const box=say('Here are the actual steps performed for this comparison. This is a deterministic workflow, not a model-driven agent trace.');for(const t of result.trace){box.append(node('h3',t.tool));paragraph(box,t.detail)}return true}
 if(action==='profile'){const box=panel('Your goals and time budget');paragraph(box,'Optional context stays in this tab or a session file you explicitly save. The weekly plan uses your available hours.');for(const [key,label,type] of [['degree','Degree / academic context','text'],['experience','Experience you want to highlight','text'],['goal','Career goal / industry','text'],['hoursPerWeek','Hours available each week','number']]){const l=node('label',label),input=node('input');input.type=type;input.value=profile[key];input.maxLength=240;input.id='profile-'+key;l.htmlFor=input.id;if(type==='number'){input.min=1;input.max=20}box.append(l,input)}const save=node('button','Use these goals','chip');save.addEventListener('click',()=>{for(const key of ['degree','experience','goal'])profile[key]=$('#profile-'+key).value.trim().slice(0,240);profile.hoursPerWeek=Math.max(1,Math.min(20,Number($('#profile-hoursPerWeek').value)||3));$('#panel').close();say('Your plan will use a weekly budget of '+profile.hoursPerWeek+' hours.'+(profile.goal?' Your stated goal: '+profile.goal:''));});box.append(save);return true}
 if(action==='save-session'){downloadSession();return true}
 if(action==='open-session'){$('#session-file').click();return true}
 if(action==='project'){const box=panel('Project evidence and readiness');paragraph(box,liveEnabled?'This local version connects one AI coach to guidance retrieval and career tools. Open Sources and agent activity on a reply to inspect its actual tool calls. Online deployment and student usefulness testing are still pending.':'This version uses offline rules. Configure a server-side API key and restart to enable AI.');const a=node('a','Open the project evidence page ↗');a.href='project.html';a.target='_blank';a.rel='noopener noreferrer';box.append(a);paragraph(box,'The page documents scope, architecture, evaluation, privacy, limitations and presentation readiness. Automated results are not student usability results.');return true}
 return false;
}
function downloadSession(){if(!resume&&!job&&!transcript.length){notify('Start a conversation first.');return}const payload={format:'career-compass-session',version:1,resume,job,role,profile,completed:[...completed]};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=node('a');a.href=url;a.download='career-compass-private-session.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Session saved. It includes resume text; store it privately.');}
$('#session-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>200000)throw Error('Choose a session file smaller than 200 KB.');const d=JSON.parse(await file.text());if(d.format!=='career-compass-session'||d.version!==1||!['resume','job','role'].every(k=>typeof d[k]==='string')||d.resume.length>40000||d.job.length>40000||d.role.length>160)throw Error('This is not a supported Career Compass session file.');reset();resume=d.resume;job=d.job;role=d.role;const raw=d.profile||{};profile={hoursPerWeek:Math.max(1,Math.min(20,Number(raw.hoursPerWeek)||3)),degree:String(raw.degree||'').slice(0,240),experience:String(raw.experience||'').slice(0,240),goal:String(raw.goal||'').slice(0,240)};say('Your saved inputs have been restored. Previous chat messages are not stored in the session file.');if(resume.length>=40&&job.length>=40){if(liveEnabled){result=analyze(resume,job,role,docs);status()}else compare();completed=new Set(Array.isArray(d.completed)?d.completed.filter(n=>Number.isInteger(n)&&n>=0&&n<4):[])}else if(resume.length>=40)askJob();else askResume();status()}catch(error){notify(error.message)}finally{$('#session-file').value=''}});

function showAnswerDraft(question,details=''){
 draftActive=true;waiting='idle';requestedTask=null;journeyStage=3;
 const request=classifyInterviewRequest(question);draftTopic=request?.topic||'custom';draftQuestion=question;
 const draft=buildAnswerDraft({question,topic:draftTopic,resume,profile,role,details});
 const box=say(draftTopic==='introduction'?'Yes—let’s build your “tell me about yourself” answer. Here is a starting draft you can personalize.':'Let’s draft a response first. Here is a starting structure you can personalize.');
 box.append(node('h3',draft.hasContext?'Starting draft using your supplied details':'Fill-in starting draft'));
 const quote=node('blockquote',draft.text,'answer-draft');box.append(quote);
 box.append(node('h3','How to make it your own'));for(const point of draft.structure)paragraph(box,point);
 paragraph(box,draft.note,'small-note');
 if(draft.evidence.length){const evidence=node('details',undefined,'supporting-details');evidence.append(node('summary','Details used from your inputs'));for(const line of draft.evidence)paragraph(evidence,line);box.append(evidence)}
 actions(box,[['Tailor this with my details','draft-details'],['Practice saying it aloud','practice-draft']]);status();scroll();
}

function setLiveBusy(busy){
 liveBusy=busy;$('#send').disabled=busy;$('#attach').disabled=busy;
 $('#chat-form').setAttribute('aria-busy',String(busy));
}
async function sendLive(text){
 const version=liveVersion;
 const inferred=inferDocumentType(text);
 if((waiting==='resume'&&text.length>=40&&!/^(can|could|what|how|why|help|please|stop|instead)\b/i.test(text))||inferred==='resume'){resume=text;result=null;completed.clear();}
 if((waiting==='job'&&text.length>=40&&!/^(can|could|what|how|why|help|please|stop|instead)\b/i.test(text))||inferred==='job'){job=text;role=text.split('\n')[0].slice(0,160);result=null;completed.clear();}
 waiting='idle';draftActive=false;
 const history=liveHistory.slice(-20);
 liveHistory.push({role:'user',content:text.slice(0,6000)});
 liveController=new AbortController();setLiveBusy(true);
 const pending=say('Reviewing your request and relevant guidance…');
 pending.setAttribute('role','status');
 status();$('#input-hint').textContent='Working on your request…';
 try{
  const response=await fetch(apiEndpoint(apiBase,'/api/chat'),{method:'POST',headers:{'Content-Type':'application/json'},signal:liveController.signal,
   body:JSON.stringify({message:text,history,context:{resume,job,role,profile,addedSources:docs.filter(d=>d.id.startsWith('custom-')).map(d=>({title:d.title,text:d.text}))}})});
  const answer=await response.json();
  if(version!==liveVersion)return;
  pending.closest('.message').remove();
  if(!response.ok)throw Error(answer.error||'The AI request failed. Please retry.');
  const box=say(answer.text);box.classList.add('live-answer');
  liveHistory.push({role:'assistant',content:answer.text.slice(0,6000)});
  const details=node('details',undefined,'supporting-details');details.append(node('summary','Sources and agent activity'));
  for(const item of answer.sources||[])source(details,item);
  if(resume.length>=40&&job.length>=40){result=analyze(resume,job,role,docs);const inputs=node('details',undefined,'evidence');inputs.append(node('summary','Resume/job evidence — independent local rule checks'));evidence(inputs,result.rows);for(const line of result.manualReview)paragraph(inputs,'Review manually: '+line);details.append(inputs);}
  for(const step of answer.trace||[])paragraph(details,step.step+'. '+step.tool+' — '+step.status,'small-note');
  paragraph(details,`${answer.model} · ${(answer.elapsedMs/1000).toFixed(1)} seconds · ${answer.usage.modelCalls} model calls · ${answer.usage.inputTokens} input / ${answer.usage.outputTokens} output tokens. Source IDs are validated; check that each passage supports the advice.`,'small-note');
  box.append(details);journeyStage=3;status();$('#coach-next-step').textContent='Ask a follow-up, change direction, or share more context. You can inspect sources and actual tool activity below each AI reply.';scroll();
 }catch(error){
  if(version!==liveVersion)return;
  pending.closest('.message')?.remove();
  say('I couldn’t complete that AI request. '+(error.name==='AbortError'?'The request was cancelled.':error.message)+' Your inputs are still available. Send your request again to retry.');
 }finally{
  if(version===liveVersion){setLiveBusy(false);liveController=null;status();$('#message').focus()}
 }
}
if(liveEnabled){
 $('.practice-badge').textContent='AI MODE';
 $('.mode-note').textContent='AI mode · Messages and supplied documents are sent to OpenAI. Verify advice and citations. Use redacted data.';
 $('.side-footer small').textContent='AI processing via OpenAI';
 $('#coach-next-step').textContent='Tell me what you need. I can draft an answer, review your experience, or help you choose a next step.';
}
